const hex = n => { let s = ''; for (let i = 0; i < n; i++) { s += Math.floor(Math.random() * 16).toString(16); } return s; };
const hexRe32 = /^[0-9a-f]{32}$/i;
const hexRe16 = /^[0-9a-f]{16}$/i;
return $input.all().map(item => {
  const j = item.json;
  const traceId = hexRe32.test(String(j.trace_id || '')) ? String(j.trace_id).toLowerCase() : hex(32);
  const parentId = hexRe16.test(String(j.parent_span_id || '')) ? String(j.parent_span_id).toLowerCase() : '';
  return { json: Object.assign({}, j, { trace_id: traceId, parent_span_id: parentId, span_id: hex(16), test_case_id: j.test_case_id || '', start_time_ns: String(Date.now()) + '000000' }) };
});

/**
 * MIRA Planner — Parse Plan Output v2.9
 *
 * Compatible with restored 11-field output schema.
 * Preserves existing Orchestrator response contract.
 * Validates milestone completeness against phase records.
 */

const trig = $('When Orchestrator Requests Plan').first().json;
const item = $input.first()?.json || {};

const base = {
  agent: 'planner',
  snapshot_id: trig.snapshot_id || '',
  generated_at: new Date().toISOString()
};

function fail(message) {
  return [{
    json: {
      ...base,
      status: 'error',
      plan: null,
      error_detail: message,
      validation_status: 'FAILED'
    }
  }];
}

if (item.error) {
  return fail(String(item.error.message || item.error));
}

let raw = item.output ?? item.text ?? '';
let parsed = null;

if (raw && typeof raw === 'object') {
  parsed = raw;
} else {
  let s = String(raw).trim();
  s = s.replace(/^```(?:json)?\s*/i, '')
       .replace(/```\s*$/i, '')
       .trim();

  try {
    parsed = JSON.parse(s);
  } catch (_) {
    const first = s.indexOf('{');
    const last = s.lastIndexOf('}');

    if (first >= 0 && last > first) {
      try {
        parsed = JSON.parse(s.slice(first, last + 1));
      } catch (_) {}
    }
  }
}

if (!parsed || typeof parsed !== 'object' ||
    Array.isArray(parsed)) {
  return fail('Planner returned invalid or empty JSON.');
}

// Handle a nested model output if supplied.
if (parsed.output && typeof parsed.output === 'object') {
  parsed = parsed.output;
}

const required = [
  'project_name',
  'objective',
  'objectives',
  'scope',
  'phases',
  'activities',
  'deliverables',
  'milestones',
  'timeline',
  'assumptions',
  'data_gaps'
];

const missingFields = required.filter(
  key => !Object.prototype.hasOwnProperty.call(parsed, key)
);

if (missingFields.length) {
  return fail(
    'Missing required fields: ' + missingFields.join(', ')
  );
}

const arrayFields = [
  'objectives',
  'phases',
  'activities',
  'deliverables',
  'milestones',
  'assumptions',
  'data_gaps'
];

const invalidArrays = arrayFields.filter(
  key => !Array.isArray(parsed[key])
);

if (invalidArrays.length) {
  return fail(
    'Invalid array fields: ' + invalidArrays.join(', ')
  );
}

const plan = {
  project_name: parsed.project_name ?? null,
  objective: parsed.objective ?? null,
  objectives: parsed.objectives,
  scope: parsed.scope ?? null,
  phases: parsed.phases,
  activities: parsed.activities,
  deliverables: parsed.deliverables,
  milestones: parsed.milestones.map(m => ({
    name: m.name ?? null,
    target_week: m.target_week ?? null,
    target_date: m.target_date ?? null,
    source_reference: m.source_reference ?? null
  })),
  timeline: parsed.timeline ?? null,
  assumptions: parsed.assumptions,
  data_gaps: parsed.data_gaps
};

// Check milestones listed within phase records.
const normalized = value =>
  String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');

const expected = [...new Set(
  plan.phases.flatMap(p =>
    Array.isArray(p.milestones_deliverables)
      ? p.milestones_deliverables
      : []
  ).map(normalized).filter(Boolean)
)];

const actual = [...new Set(
  plan.milestones.map(m => normalized(m.name)).filter(Boolean)
)];

const actualSet = new Set(actual);
const missingMilestones = expected.filter(
  name => !actualSet.has(name)

);
const expectedSet = new Set(expected);

const unexpectedMilestones = actual.filter(
  name => !expectedSet.has(name)
);

const validationIssues = [];

if (expected.length && missingMilestones.length) {
  validationIssues.push(
    `Only ${expected.length - missingMilestones.length} ` +
    `of ${expected.length} phase deliverables are ` +
    `represented as milestones. Missing: ` +
    missingMilestones.join('; ')
  );
}

if (unexpectedMilestones.length) {
  validationIssues.push(
    'Milestones not represented in phase ' +
    'deliverables: ' +
    unexpectedMilestones.join('; ')
  );
}


if (plan.phases.length === 0) {
  validationIssues.push('No project phases returned.');
}

if (!plan.project_name) {
  validationIssues.push('Project name missing.');
}

const passed = validationIssues.length === 0;

return [{
  json: {
    ...base,
    status: passed ? 'ok' : 'error',
    plan: passed ? plan : null,
    ...(passed ? {} : {
      error_detail: validationIssues.join(' | ')
    }),
    validation_status: passed ? 'PASSED' : 'FAILED',
    validation_issues: validationIssues,
    phase_count: plan.phases.length,
    milestone_count: plan.milestones.length,
    expected_milestone_count: expected.length,
    milestone_completeness_pct: expected.length
      ? Number(
          ((expected.length - missingMilestones.length) /
           expected.length * 100).toFixed(2)
        )
      : null
  }
}];

